"use client";
/* eslint-disable @next/next/no-img-element -- QR is an SVG data URI generated by our API */

import { type FormEvent, useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { Field } from "@/components/ui/Field";
import { ApiError, api } from "@/lib/api/client";
import styles from "./auth.module.css";

interface Status { enabled: boolean; required: boolean }
interface Setup { otpauth_uri: string; qr_svg: string; secret: string }

export function TwoFactorPanel() {
  const [status, setStatus] = useState<Status | null>(null);
  const [setup, setSetup] = useState<Setup | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const c = new AbortController();
    api<Status>("/api/v1/auth/mfa", { signal: c.signal }).then(setStatus).catch(() => undefined);
    return () => c.abort();
  }, []);

  async function start() {
    setError(null);
    try {
      setSetup(await api<Setup>("/api/v1/auth/mfa/setup", { method: "POST" }));
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Could not start setup.");
    }
  }

  async function confirm(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const code = String(new FormData(e.currentTarget).get("code") ?? "");
    try {
      setStatus(await api<Status>("/api/v1/auth/mfa/confirm", { method: "POST", body: JSON.stringify({ code }) }));
      setSetup(null);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "That code did not work.");
    }
  }

  if (!status) return null;
  return (
    <section aria-labelledby="mfa-title" className={styles.card} style={{ boxShadow: "none" }}>
      <h2 id="mfa-title">Two-factor login</h2>
      {status.enabled ? (
        <p className={styles.muted}>On. You will be asked for a code from your authenticator app when you log in.</p>
      ) : (
        <>
          <p className={styles.muted}>
            {status.required ? "Required for your role before you can use staff tools. " : ""}
            Use Google Authenticator, Microsoft Authenticator or any TOTP app.
          </p>
          {setup ? (
            <form onSubmit={(e) => void confirm(e)} className={styles.card} style={{ boxShadow: "none" }}>
              <img src={`data:image/svg+xml;utf8,${encodeURIComponent(setup.qr_svg)}`} alt="QR code to add RedStarVibe to your authenticator app" width={180} height={180} />
              <p className={styles.muted}>Can&apos;t scan? Enter this key: <code>{setup.secret}</code></p>
              <Field label="6-digit code" name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" required />
              <Button type="submit">Turn on</Button>
            </form>
          ) : (
            <Button variant="secondary" onClick={() => void start()}>Set up two-factor login</Button>
          )}
        </>
      )}
      {error ? <p className={styles.formError} role="alert">{error}</p> : null}
    </section>
  );
}
